/* Signature Quechua Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Sisakilla": "From sisa (flower) + killa (moon): 'moon flower'.", "Wayrainti": "From wayra (wind) + inti (sun): 'sun wind'.", "Killawayra": "From killa (moon) + wayra (wind): 'moon wind'.", "Intisisam": "From inti (sun) + sisa (flower): 'sun flower'.", "Yupanquisisa": "From yupanqui + sisa.", "Tupackilla": "From tupac (shining) + killa (moon): 'shining moon'.", "Sisahuaman": "Signature surname combining sisa + huaman (falcon).", "Wayracondori": "Signature surname combining wayra + condori.", "Killamamani": "Signature surname combining killa + mamani.", "Intiquispe": "Signature surname combining inti + quispe."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Sisakilla';
console.log(lookup(q));

